package dev.eugheist.tc4modern;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;
/** ModelManaPod box geometry and original TileManaPodRenderer growth tint/pulse. */
public final class ManaPodRenderer implements BlockEntityRenderer<ManaPodEntity>{
 private final ModelPart inner,outer;
 public ManaPodRenderer(BlockEntityRendererProvider.Context c){var mesh=new MeshDefinition();mesh.getRoot().addOrReplaceChild("inner",CubeListBuilder.create().texOffs(0,0).mirror().addBox(-2,0,-2,4,5,4),PartPose.ZERO);mesh.getRoot().addOrReplaceChild("outer",CubeListBuilder.create().texOffs(0,0).mirror().addBox(-3.5f,0,-3.5f,7,9,7),PartPose.ZERO);var root=LayerDefinition.create(mesh,32,32).bakeRoot();inner=root.getChild("inner");outer=root.getChild("outer");}
 @Override public void render(ManaPodEntity pod,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){int age=pod.getBlockState().getValue(ManaPodBlock.AGE);if(age<2)return;var mc=net.minecraft.client.Minecraft.getInstance();float time=(mc.player==null?0:mc.player.tickCount)+partial;float pulse=(float)Math.sin((time+pod.getBlockPos().hashCode()%100)/8)*.1f+.9f;int base=0x259d75,color=base;if(pod.aspect!=null){int a=pod.aspect.getColor();if(age==7)color=a;else{int m=age-2;color=(((base>>16&255)+(a>>16&255)*m)/(m+1)<<16)|(((base>>8&255)+(a>>8&255)*m)/(m+1)<<8)|((base&255)+(a&255)*m)/(m+1);}}pose.pushPose();pose.translate(.5,.75,.5);pose.mulPose(com.mojang.math.Axis.XP.rotationDegrees(180));if(age>2){pose.pushPose();pose.translate(0,.1,0);float scale=.125f*age*pulse;pose.scale(scale,scale,scale);inner.render(pose,buffers.getBuffer(RenderType.entityTranslucent(AlchemyContent.id("textures/models/manapod_0.png"))),net.minecraft.client.renderer.LightTexture.pack(Math.min(15,(int)((age*10+150*pulse)/16)),0),overlay);pose.popPose();}float scale=.15f*age;pose.scale(scale,scale,scale);outer.render(pose,buffers.getBuffer(RenderType.entityTranslucent(AlchemyContent.id("textures/models/manapod_2.png"))),light,overlay,0xe6000000|color);pose.popPose();}
}
